var response = await client.GiftCards.ListGiftCardsAsync(
    new Dictionary<string, object?> { ["email"] = "jane.doe@example.com", ["is_active"] = "true" });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var giftCard in ((IReadOnlyList<object?>)body["gift_cards"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{giftCard["id"]} {giftCard["code"]} {giftCard["balance"]} {giftCard["initial_amount"]} {giftCard["is_active"]}");
var pagination = (IReadOnlyDictionary<string, object?>)body["pagination"]!;
Console.WriteLine($"{pagination["total"]} {pagination["has_next"]}");
